INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.86.0',
  '2026-09-16',
  'Пульт ТВ: медиатека с постерами, сезоны подряд и очередь',
  E'На приставке после «Начать» появился переключатель: «Визуальный» (теперь по умолчанию) и «Файлы» — прежнее дерево папок. Визуальный режим собирает все библиотеки в одну медиатеку: разделы «Сериалы», «Фильмы» и «Музыка», плитки с постерами. Постеры плеер находит сам и сохраняет рядом с фильмом или сериалом; если попался не тот — положите свою картинку с тем же именем, она главнее.\n\nПлеер открывается, только когда выбрали, что смотреть: фильм — сразу, сериал — экран с сезонами и сериями, музыка — список треков. Назад из плеера ставит на паузу, а на главной появляется «Продолжить».\n\nСериал теперь идёт сезон за сезоном: после последней серии сезона сама начинается первая серия следующего — и в визуальном режиме, и в «Файлах».\n\nНа главной можно собрать очередь: «＋ В очередь» под фильмом или сериалом, дальше «Смотреть очередь» — всё играет по порядку, сериалы целиком. Очередь переживает перезагрузку страницы.\n\nНа странице «Пульт ТВ» у поля кода появились кнопки «Вставить» и «Очистить».',
  E'Агент: GET /api/catalog раскладывает библиотеки по структуре папок без ffprobe (сериал — папка с папками-сезонами, фильм — файл или папка с одним файлом, музыка — папки с треками); GET /api/item — один файл с разбором; GET /api/next-season — серии следующей папки того же сериала (папки прямо в корне библиотеки сезонами не считаются, иначе фильм «А/» продолжился бы фильмом «Б/»); GET /poster/{id} — постер: рядом лежащий файл, иначе поиск. Источники без ключей: подсказки IMDb (фильм против сериала и год — отличает «The Gentlemen» 2019 года от сериала 2024-го; картинка режется суффиксом CDN с 5 МБ до 40 КБ) и Википедия для кириллицы (pilicense=any обязателен — постеры несвободные). Совпадение названия обязательно: одно слово «сериал» в заголовке страницы подсунуло «Чернобыль» на выдуманное название. Промах помнится сутки, поиск по одной плитке за раз, не больше двух в интернет разом. cleanTitle вынимает название и год из релизных имён; год берётся из скобок или последний подходящий, иначе в «Blade Runner 2049 (2017)» годом стал бы 2049 — покрыто catalog_test.go.\n\nПлеер переписан: общая шапка с переключателем, пространственная навигация стрелками по сетке плиток, сезон за сезоном через next-season (очередь грузится лениво, чтобы не разбирать все двенадцать сезонов разом), очередь с главной в localStorage. Отменённый play() при переключении серии больше не затирает название ошибкой.\n\nПульт: общий shared/clipboard.ts (Clipboard API, затем Telegram WebApp) вместо копии в Links; нет доступа к буферу — фокус в поле и подсказка про долгое нажатие.\n\nПроверено на тестовой библиотеке в браузере и на живом агенте: раскладка, постеры, переход S01→S02 в обоих режимах, конец сериала, очередь фильм → мини-сериал, музыка, команда с пульта в визуальном режиме.'
);
-- +goose StatementEnd

